using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using MySqlConnector;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class ClientesController:Controller {private readonly Db _db;private readonly SecurityService _sec;public ClientesController(Db db,SecurityService sec){_db=db;_sec=sec;}public IActionResult Index(){var l=new List<Cliente>();using var x=_db.Open();using var c=new MySqlCommand("SELECT * FROM cliente ORDER BY nome",x);using var r=c.ExecuteReader();while(r.Read()){var cpf=_sec.Decrypt(r.GetString("cpf_cifrado"));l.Add(new Cliente{Id=r.GetInt32("id"),Nome=r.GetString("nome"),CPF=cpf.Length>=4?"***.***."+cpf[^4..]:"***",Status=r.GetString("status")});}return View(l);}[HttpGet]public IActionResult Create()=>View(new Cliente{DataNascimento=DateTime.Today,Status="ativo"});[HttpPost][ValidateAntiForgeryToken]public IActionResult Create(Cliente c){if(string.IsNullOrWhiteSpace(c.Nome)||string.IsNullOrWhiteSpace(c.CPF)){ModelState.AddModelError("","Nome e CPF são obrigatórios.");return View(c);}using var x=_db.Open();using var cmd=new MySqlCommand("INSERT INTO cliente(nome,cpf_hash,cpf_cifrado,nascimento_cif,telefone_cif,email_cif,endereco_cif,observacoes_cif,status) VALUES(@n,@h,@cpf,@d,@t,@e,@en,@o,@s)",x);var cpf=SecurityService.Digits(c.CPF);cmd.Parameters.AddWithValue("@n",c.Nome);cmd.Parameters.AddWithValue("@h",_sec.Hmac(cpf));cmd.Parameters.AddWithValue("@cpf",_sec.Encrypt(cpf));cmd.Parameters.AddWithValue("@d",_sec.Encrypt(c.DataNascimento.ToString("yyyy-MM-dd")));cmd.Parameters.AddWithValue("@t",_sec.Encrypt(c.Telefone??""));cmd.Parameters.AddWithValue("@e",_sec.Encrypt(c.Email??""));cmd.Parameters.AddWithValue("@en",_sec.Encrypt(c.Endereco??""));cmd.Parameters.AddWithValue("@o",_sec.Encrypt(c.Observacoes??""));cmd.Parameters.AddWithValue("@s",c.Status??"ativo");try{cmd.ExecuteNonQuery();return RedirectToAction(nameof(Index));}catch(MySqlException){ModelState.AddModelError("CPF","CPF já cadastrado.");return View(c);}}[HttpPost][ValidateAntiForgeryToken]public IActionResult Delete(int id){using var x=_db.Open();using var check=new MySqlCommand("SELECT COUNT(*) FROM agendamento WHERE cliente_id=@id AND situacao='concluido'",x);check.Parameters.AddWithValue("@id",id);if(Convert.ToInt64(check.ExecuteScalar())>0){using var u=new MySqlCommand("UPDATE cliente SET status='inativo' WHERE id=@id",x);u.Parameters.AddWithValue("@id",id);u.ExecuteNonQuery();}else{using var d=new MySqlCommand("DELETE FROM cliente WHERE id=@id",x);d.Parameters.AddWithValue("@id",id);d.ExecuteNonQuery();}return RedirectToAction(nameof(Index));}}
